-- Dlogix courier rate cards — data snapshot exported from the dev DB.
-- Loads DHL + FedEx rate cards, zones and rate rows into prod EXACTLY as dev
-- (incl. tuned config: fuel order, margins, fuel %, currency rates).
--
-- Load into prod (from the repo on the server):
--   docker cp deploy/seed-data/courier-rate-cards.sql ddecor_db:/tmp/courier.sql
--   docker exec -it ddecor_db psql -h 127.0.0.1 -U dlogix -d dlogix -f /tmp/courier.sql
-- (enter the dlogix DB password when prompted)
--
-- Idempotent: truncates the 3 courier tables first, so re-running is safe.
BEGIN;
TRUNCATE TABLE public.courier_rate_rows, public.courier_zones, public.courier_rate_cards CASCADE;
